def ploscha(a, b):
    return a * b
print(ploscha(3, 4))

def kilkist_dod(nums):
    return sum(1 for x in nums if x > 0)
print(kilkist_dod([1, -1, 2]))

def ocinka(bal):
    if bal >= 10:
        return "відмінно"
    if bal >= 7:
        return "добре"
    return "треба ще"
print(ocinka(7))
